import React, { useState ,useEffect} from 'react';
import Art from './Art';
import { useDataLayerValue } from '../DataLayer'



function Gallery({data}) {

    const [{page},dispatch] = useDataLayerValue();

    const profilePage = () => {
        dispatch({
          type: "SET_PAGE",
          page: "profile",
        });
    }


    return(
        <div className={"flex flex-wrap content-center justify-center h-screen w-screen block"}>
              <div onClick={profilePage} className={"text-center text-4xl m-8 font-mono italic bold"}>Keenan Cassidy</div>
              <div className={"flex justify-center overflow-x-auto"}>
                {data.map((items, index) => {return (
                      <div  className={"my-2"}>
                        <Art key={index} piece={items} />
                      </div>
                    );
                })}
            </div>
        </div>

    )
}

export default Gallery
